def compress(s):
    if not s:
        return s
    parts = []
    count = 1
    for i in range(1, len(s) + 1):
        if i < len(s) and s[i] == s[i - 1]:
            count += 1
        else:
            parts.append(f'{s[i - 1]}{count}')
            count = 1
    out = ''.join(parts)
    return out if len(out) < len(s) else s

